{"title": "[Tropobeat] CCI ops: ducting and episodes by hour", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "autosize": {
  "type": "fit",
  "contains": "padding"
 },
 "padding": {
  "left": 20,
  "right": 20,
  "top": 18,
  "bottom": 12
 },
 "background": "#0F1F2C",
 "config": {
  "view": {
   "stroke": null
  },
  "legend": {
   "labelColor": "#8DA2B2",
   "labelFont": "ui-monospace,Menlo,Consolas,monospace",
   "labelFontSize": 11.5,
   "symbolType": "square",
   "symbolSize": 100,
   "symbolStrokeWidth": 0,
   "columnPadding": 14,
   "layout": {
    "top": {
     "anchor": "end"
    }
   }
  },
  "text": {
   "font": "\"Inter\",\"Segoe UI\",system-ui,sans-serif",
   "fill": "#E4EDF3"
  }
 },
 "title": {
  "text": "Ducting and episodes, by hour",
  "subtitle": {
   "signal": "'LOCAL TIME (UTC' + timeFormat(now(), '%Z') + ')' + ' · DASHBOARD TIME RANGE'"
  },
  "anchor": "start",
  "frame": "group",
  "offset": 12,
  "color": "#E4EDF3",
  "font": "\"Barlow Condensed\",\"Roboto Condensed\",\"Arial Narrow\",sans-serif",
  "fontSize": 22,
  "fontWeight": 600,
  "subtitleColor": "#8DA2B2",
  "subtitleFont": "ui-monospace,Menlo,Consolas,monospace",
  "subtitleFontSize": 11,
  "subtitlePadding": 4
 },
 "signals": [
  {
   "name": "lab",
   "value": 22
  },
  {
   "name": "mid",
   "value": 18
  },
  {
   "name": "ax",
   "value": 18
  },
  {
   "name": "avail",
   "update": "max(80, height - 2 * lab - mid - ax)"
  },
  {
   "name": "h1",
   "update": "floor(avail * 0.45)"
  },
  {
   "name": "h2",
   "update": "avail - h1"
  },
  {
   "name": "y2",
   "update": "2 * lab + h1 + mid"
  },
  {
   "name": "vorder",
   "value": [
    "cci_confirmed",
    "dual_unexplained",
    "dual_ducting_unknown",
    "one_side"
   ]
  },
  {
   "name": "vlabel",
   "value": {
    "cci_confirmed": "CCI",
    "dual_unexplained": "UNEXPLAINED",
    "dual_ducting_unknown": "DUCTING UNKNOWN",
    "one_side": "ONE SIDE"
   }
  }
 ],
 "data": [
  {
   "name": "ductRaw",
   "format": {
    "property": "aggregations.h.buckets"
   },
   "url": {
    "index": "tropobeat-*",
    "body": {
     "size": 0,
     "aggs": {
      "h": {
       "date_histogram": {
        "field": "@timestamp",
        "fixed_interval": "1h",
        "min_doc_count": 0,
        "extended_bounds": {
         "min": {
          "%timefilter%": "min"
         },
         "max": {
          "%timefilter%": "max"
         }
        }
       },
       "aggs": {
        "p": {
         "cardinality": {
          "field": "tropobeat.path_ids"
         }
        }
       }
      }
     },
     "query": {
      "bool": {
       "must": [
        "%dashboard_context-must_clause%",
        {
         "range": {
          "@timestamp": {
           "%timefilter%": true
          }
         }
        },
        {
         "term": {
          "metricset.name": "weather"
         }
        },
        {
         "range": {
          "tropobeat.ducting_level": {
           "gte": 2
          }
         }
        }
       ],
       "must_not": [
        "%dashboard_context-must_not_clause%"
       ],
       "filter": [
        "%dashboard_context-filter_clause%"
       ]
      }
     }
    }
   }
  },
  {
   "name": "duct",
   "source": "ductRaw",
   "transform": [
    {
     "type": "formula",
     "as": "n",
     "expr": "datum.p.value"
    },
    {
     "type": "extent",
     "field": "n",
     "signal": "ductExt"
    }
   ]
  },
  {
   "name": "epsRaw",
   "format": {
    "property": "aggregations.h.buckets"
   },
   "url": {
    "index": "tropobeat-*",
    "body": {
     "size": 0,
     "aggs": {
      "h": {
       "date_histogram": {
        "field": "@timestamp",
        "fixed_interval": "1h",
        "min_doc_count": 0,
        "extended_bounds": {
         "min": {
          "%timefilter%": "min"
         },
         "max": {
          "%timefilter%": "max"
         }
        }
       },
       "aggs": {
        "s": {
         "terms": {
          "field": "tropobeat.correlation.state",
          "size": 10
         },
         "aggs": {
          "e": {
           "cardinality": {
            "field": "tropobeat.correlation.episode.id"
           }
          }
         }
        }
       }
      }
     },
     "query": {
      "bool": {
       "must": [
        "%dashboard_context-must_clause%",
        {
         "range": {
          "@timestamp": {
           "%timefilter%": true
          }
         }
        },
        {
         "term": {
          "metricset.name": "correlation"
         }
        }
       ],
       "must_not": [
        "%dashboard_context-must_not_clause%",
        {
         "term": {
          "tropobeat.correlation.state": "clear"
         }
        }
       ],
       "filter": [
        "%dashboard_context-filter_clause%"
       ]
      }
     }
    }
   }
  },
  {
   "name": "eps",
   "source": "epsRaw",
   "transform": [
    {
     "type": "flatten",
     "fields": [
      "s.buckets"
     ],
     "as": [
      "sb"
     ]
    },
    {
     "type": "formula",
     "as": "verdict",
     "expr": "datum.sb.key == 'single_side' || datum.sb.key == 'unpaired' ? 'one_side' : datum.sb.key"
    },
    {
     "type": "formula",
     "as": "c",
     "expr": "datum.sb.e.value"
    },
    {
     "type": "aggregate",
     "groupby": [
      "key",
      "verdict"
     ],
     "fields": [
      "c"
     ],
     "ops": [
      "sum"
     ],
     "as": [
      "n"
     ]
    },
    {
     "type": "formula",
     "as": "o",
     "expr": "indexof(vorder, datum.verdict)"
    },
    {
     "type": "stack",
     "groupby": [
      "key"
     ],
     "field": "n",
     "sort": {
      "field": "o"
     },
     "as": [
      "y0",
      "y1"
     ]
    },
    {
     "type": "extent",
     "field": "y1",
     "signal": "epsExt"
    }
   ]
  },
  {
   "name": "hours",
   "source": "ductRaw",
   "transform": [
    {
     "type": "project",
     "fields": [
      "key"
     ]
    }
   ]
  },
  {
   "name": "legend",
   "values": [
    {
     "label": "ONE SIDE",
     "color": "#5D7C91",
     "dx": 73
    },
    {
     "label": "DUCTING UNKNOWN",
     "color": "#A88A4A",
     "dx": 212
    },
    {
     "label": "UNEXPLAINED",
     "color": "#E0A458",
     "dx": 322
    },
    {
     "label": "CCI",
     "color": "#FF6B5E",
     "dx": 375
    }
   ]
  }
 ],
 "scales": [
  {
   "name": "x",
   "type": "band",
   "range": "width",
   "paddingInner": 0.18,
   "paddingOuter": 0.04,
   "domain": {
    "fields": [
     {
      "data": "ductRaw",
      "field": "key"
     },
     {
      "data": "epsRaw",
      "field": "key"
     }
    ],
    "sort": true
   }
  },
  {
   "name": "yd",
   "type": "linear",
   "nice": true,
   "zero": true,
   "domain": {
    "signal": "[0, max(10, ductExt[1] || 0)]"
   },
   "range": [
    {
     "signal": "lab + h1"
    },
    {
     "signal": "lab"
    }
   ]
  },
  {
   "name": "ye",
   "type": "linear",
   "nice": true,
   "zero": true,
   "domain": {
    "signal": "[0, max(4, epsExt[1] || 0)]"
   },
   "range": [
    {
     "signal": "y2 + h2"
    },
    {
     "signal": "y2"
    }
   ]
  },
  {
   "name": "color",
   "type": "ordinal",
   "domain": [
    "cci_confirmed",
    "dual_unexplained",
    "dual_ducting_unknown",
    "one_side"
   ],
   "range": [
    "#FF6B5E",
    "#E0A458",
    "#A88A4A",
    "#5D7C91"
   ]
  }
 ],
 "marks": [
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "signal": "lab - 8"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 11.5
     },
     "fill": {
      "value": "#F2B84B"
     },
     "text": {
      "signal": "'PATHS DUCTING OR TRAPPING · 0–' + domain('yd')[1]"
     }
    }
   }
  },
  {
   "type": "rect",
   "from": {
    "data": "duct"
   },
   "encode": {
    "update": {
     "x": {
      "scale": "x",
      "field": "key"
     },
     "width": {
      "scale": "x",
      "band": 1
     },
     "y": {
      "scale": "yd",
      "field": "n"
     },
     "y2": {
      "scale": "yd",
      "value": 0
     },
     "fill": {
      "value": "rgba(242,184,75,0.85)"
     },
     "cornerRadiusTopLeft": {
      "value": 2
     },
     "cornerRadiusTopRight": {
      "value": 2
     },
     "tooltip": {
      "signal": "{title: timeFormat(datum.key, '%d %b %H:00'), 'Paths ducting or trapping': datum.n}"
     }
    },
    "hover": {
     "fill": {
      "value": "#F2B84B"
     }
    }
   }
  },
  {
   "type": "rule",
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "x2": {
      "signal": "width"
     },
     "y": {
      "signal": "lab + h1 + 0.5"
     },
     "stroke": {
      "value": "#22384A"
     }
    }
   }
  },
  {
   "type": "text",
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "y": {
      "signal": "y2 - 8"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 11.5
     },
     "fill": {
      "value": "#8DA2B2"
     },
     "text": {
      "signal": "'OPEN EPISODES BY VERDICT · 0–' + domain('ye')[1]"
     }
    }
   }
  },
  {
   "type": "rect",
   "from": {
    "data": "legend"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "width - datum.dx"
     },
     "y": {
      "signal": "y2 - 8 - 9"
     },
     "width": {
      "value": 10
     },
     "height": {
      "value": 10
     },
     "fill": {
      "field": "color"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "legend"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "width - datum.dx + 16"
     },
     "y": {
      "signal": "y2 - 8"
     },
     "text": {
      "field": "label"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 11.5
     },
     "fill": {
      "value": "#8DA2B2"
     }
    }
   }
  },
  {
   "type": "rect",
   "from": {
    "data": "eps"
   },
   "encode": {
    "update": {
     "x": {
      "scale": "x",
      "field": "key"
     },
     "width": {
      "scale": "x",
      "band": 1
     },
     "y": {
      "scale": "ye",
      "field": "y1"
     },
     "y2": {
      "scale": "ye",
      "field": "y0"
     },
     "fill": {
      "scale": "color",
      "field": "verdict"
     },
     "stroke": {
      "value": "#0F1F2C"
     },
     "strokeWidth": {
      "value": 1
     },
     "opacity": {
      "value": 1
     },
     "tooltip": {
      "signal": "{title: timeFormat(datum.key, '%d %b %H:00'), 'Verdict': vlabel[datum.verdict], 'Open episodes': datum.n}"
     }
    },
    "hover": {
     "opacity": {
      "value": 0.8
     }
    }
   }
  },
  {
   "type": "rule",
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "x2": {
      "signal": "width"
     },
     "y": {
      "signal": "y2 + h2 + 0.5"
     },
     "stroke": {
      "value": "#22384A"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "hours"
   },
   "encode": {
    "update": {
     "x": {
      "scale": "x",
      "field": "key",
      "band": 0.5
     },
     "y": {
      "signal": "y2 + h2 + 5"
     },
     "align": {
      "value": "center"
     },
     "baseline": {
      "value": "top"
     },
     "text": {
      "signal": "bandwidth('x') >= 18 || hours(datum.key) % 3 == 0 ? timeFormat(datum.key, '%H') : ''"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 10.5
     },
     "fill": {
      "value": "#8DA2B2"
     }
    }
   }
  }
 ]
}"}}
